export const isOnePiece = (n: FloorStandingToiletNode) =>
  (n.construction ?? (n.design.startsWith('one-piece') ? 'one-piece' : 'two-piece')) === 'one-piece'
export function toiletLayout(n: FloorStandingToiletNode) {
  const external = n.tankType !== 'concealed'
  const rearSpace = n.tankType === 'attached' ? n.tankDepth : 0
  const tankBottom =
    n.tankType === 'attached'
      ? n.mountingHeight + (isOnePiece(n) ? 0.005 : n.couplingGap)
      : Math.max(
          n.mountingHeight + 0.08,
          n.tankType === 'high-level' ? Math.max(1.5, n.tankBottom) : n.tankBottom,
        )
  return {
    external,
    rearSpace,
    projection: n.depth + rearSpace,
    tankBottom,
    totalHeight: Math.max(
      n.mountingHeight +
        n.seatThickness +
        (n.lidEnabled ? (n.lidOpen ? n.depth + 0.005 : 0.015) : 0),
      external ? tankBottom + n.tankHeight + n.tankLidThickness : 0,
    ),
  }
}
